contract InvMutTest {
    C c;
    bool targetRan;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    fallback() external payable { targetRan = true; }
    receive() external payable {}

    function runTest(bytes calldata data) public {
        require(msg.sender != c.Owner());
        c.Command(address(this), data); if (__ESBMC_reverted()) return;
        assert(!targetRan);
    }
}

