contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;
    bool targetRan;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _runTest(bytes memory data) internal {
        vm.assume(msg.sender != c.Owner());
        try c.Command(address(this), data) {} catch { return; }
        assertTrue(!targetRan);
    }

    function testFuzz_runTest(bytes memory data) public {
        _runTest(data);
    }

    fallback() external payable { targetRan = true; }

    receive() external payable {}
}
